import java.io.*;
import java.util.*;

public class lets_do {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        st.resetSyntax();
        st.whitespaceChars(0, 32);
        st.wordChars(33, 255);
        st.nextToken();
        int n = Integer.parseInt(st.sval);
        st.nextToken();
        int b = Integer.parseInt(st.sval);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            st.nextToken();
            a[i] = Integer.parseInt(st.sval);
        }
        int even = 0, odd = 0;
        int[] pe = new int[n];
        int[] po = new int[n];
        for (int i = 0; i < n; i++) {
            if ((a[i] & 1) == 0) even++;
            else odd++;
            pe[i] = even;
            po[i] = odd;
        }
        List<Integer> weights = new ArrayList<>();
        for (int i = 1; i < n - 2; i += 2) {
            if (pe[i] == po[i]) {
                weights.add(Math.abs(a[i + 1] - a[i]));
            }
        }
        int[] dp = new int[b + 1];
        for (int w : weights) {
            for (int cap = b; cap >= w; cap--) {
                dp[cap] = Math.max(dp[cap], dp[cap - w] + 1);
            }
        }
        System.out.println(dp[b]);
    }
}
